import { useMemo, useState, useRef } from "react";
import { Download, Upload, Database, AlertTriangle, Check } from "lucide-react";
import { useAppStore } from "@/store/app";

// 可备份的内容分类
interface BackupCategory {
  key: string;
  label: string;
  emoji: string;
  desc: string;
  // 从 state 取数据
  pick: (s: any) => any;
}

const CATEGORIES: BackupCategory[] = [
  {
    key: "contacts",
    label: "联系人与字卡库",
    emoji: "👥",
    desc: "所有联系人、字卡库内容",
    pick: (s) => s.contacts,
  },
  {
    key: "conversations",
    label: "聊天记录",
    emoji: "💬",
    desc: "所有会话的消息记录",
    pick: (s) => s.conversations,
  },
  {
    key: "cardGroups",
    label: "字卡分组",
    emoji: "🗂️",
    desc: "字卡的分类分组",
    pick: (s) => s.cardGroups,
  },
  {
    key: "songs",
    label: "歌曲库",
    emoji: "🎵",
    desc: "收藏的音乐列表",
    pick: (s) => s.songs,
  },
  {
    key: "stickers",
    label: "表情包",
    emoji: "😀",
    desc: "收藏的表情包图片",
    pick: (s) => s.stickers,
  },
  {
    key: "beauty",
    label: "美化设置",
    emoji: "🎨",
    desc: "主题、字体、头像、昵称等",
    pick: (s) => s.beauty,
  },
  {
    key: "chat",
    label: "聊天设置",
    emoji: "⚙️",
    desc: "回复速度、自动消息等设置",
    pick: (s) => s.chat,
  },
  {
    key: "callRecords",
    label: "通话记录",
    emoji: "📞",
    desc: "历史通话记录",
    pick: (s) => s.callRecords,
  },
  {
    key: "memos",
    label: "备忘录/信箱",
    emoji: "📝",
    desc: "信件与备忘",
    pick: (s) => s.memos,
  },
  {
    key: "bottle",
    label: "漂流瓶数据",
    emoji: "🍾",
    desc: "漂流瓶、日记、字卡库",
    pick: (s) => ({ driftBottles: s.driftBottles, bottleData: s.bottleData }),
  },
  {
    key: "tomatoStats",
    label: "番茄统计",
    emoji: "🍅",
    desc: "番茄投掷统计数据",
    pick: (s) => s.tomatoStats,
  },
];

export default function BackupPanel() {
  const [status, setStatus] = useState<string>("");
  const [error, setError] = useState<string>("");
  const [selected, setSelected] = useState<Record<string, boolean>>(
    () => Object.fromEntries(CATEGORIES.map((c) => [c.key, true]))
  );
  const fileRef = useRef<HTMLInputElement>(null);

  const state = useAppStore.getState();

  // 预估每项的大小
  const sizeInfo = useMemo(() => {
    const info: Record<string, number> = {};
    CATEGORIES.forEach((c) => {
      try {
        info[c.key] = JSON.stringify(c.pick(state) ?? null).length;
      } catch {
        info[c.key] = 0;
      }
    });
    return info;
  }, [state]);

  const selectedSizeKB = useMemo(() => {
    const total = CATEGORIES.reduce(
      (sum, c) => sum + (selected[c.key] ? sizeInfo[c.key] || 0 : 0),
      0
    );
    return (total / 1024).toFixed(1);
  }, [selected, sizeInfo]);

  const totalSizeKB = useMemo(() => {
    const total = CATEGORIES.reduce((sum, c) => sum + (sizeInfo[c.key] || 0), 0);
    return (total / 1024).toFixed(1);
  }, [sizeInfo]);

  const selectedCount = CATEGORIES.filter((c) => selected[c.key]).length;

  const toggle = (key: string) =>
    setSelected((s) => ({ ...s, [key]: !s[key] }));

  const selectAll = () =>
    setSelected(Object.fromEntries(CATEGORIES.map((c) => [c.key, true])));

  const selectNone = () =>
    setSelected(Object.fromEntries(CATEGORIES.map((c) => [c.key, false])));

  const handleBackup = () => {
    try {
      if (selectedCount === 0) {
        setError("请至少选择一项要备份的内容");
        setStatus("");
        return;
      }

      const st = useAppStore.getState();
      const backupData: Record<string, any> = {
        version: 3,
        exportTime: new Date().toISOString(),
        selectedCategories: CATEGORIES.filter((c) => selected[c.key]).map((c) => c.key),
      };

      CATEGORIES.forEach((c) => {
        if (!selected[c.key]) return;
        const val = c.pick(st);
        if (c.key === "bottle") {
          // bottle 拆成两个字段
          backupData.driftBottles = val.driftBottles;
          backupData.bottleData = val.bottleData;
        } else {
          backupData[c.key] = val;
        }
      });

      // 会话状态（轻量，便于恢复时还原打开的会话）
      if (selected.conversations) {
        backupData.groupConversationId = st.groupConversationId;
        backupData.activeConversationId = st.activeConversationId;
      }

      const json = JSON.stringify(backupData, null, 2);
      const blob = new Blob([json], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      const now = new Date();
      const ts = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, "0")}${String(now.getDate()).padStart(2, "0")}_${String(now.getHours()).padStart(2, "0")}${String(now.getMinutes()).padStart(2, "0")}`;
      a.href = url;
      a.download = `backup_${ts}.json`;
      a.click();
      URL.revokeObjectURL(url);

      const sizeKB = (blob.size / 1024).toFixed(1);
      setStatus(`备份成功！已导出 ${selectedCount} 项，文件大小 ${sizeKB} KB`);
      setError("");
    } catch (e) {
      setError(`备份失败：${e instanceof Error ? e.message : String(e)}`);
      setStatus("");
    }
  };

  const handleRestore = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const data = JSON.parse(ev.target?.result as string);
        if (!data || (typeof data !== "object")) {
          setError("文件格式不正确，不是有效的备份文件");
          setStatus("");
          return;
        }

        const st = useAppStore.getState();
        const patch: Record<string, any> = {};
        const restored: string[] = [];

        // 兼容旧版全量备份（v2）：没有 selectedCategories 时恢复全部字段
        const isLegacy = !data.selectedCategories;

        CATEGORIES.forEach((c) => {
          if (c.key === "bottle") {
            const hasBottle = data.driftBottles !== undefined || data.bottleData !== undefined;
            if (hasBottle && (isLegacy || data.selectedCategories.includes("bottle"))) {
              patch.driftBottles = data.driftBottles || [];
              patch.bottleData = data.bottleData || {};
              restored.push("漂流瓶数据");
            }
            return;
          }
          if (data[c.key] !== undefined && (isLegacy || data.selectedCategories.includes(c.key))) {
            patch[c.key] = data[c.key];
            restored.push(c.label);
          }
        });

        // 会话状态
        if (data.groupConversationId !== undefined && (isLegacy || data.selectedCategories?.includes("conversations"))) {
          patch.groupConversationId = data.groupConversationId;
        }
        if (data.activeConversationId !== undefined && (isLegacy || data.selectedCategories?.includes("conversations"))) {
          patch.activeConversationId = data.activeConversationId;
        }

        if (restored.length === 0) {
          setError("备份文件中未发现可恢复的内容");
          setStatus("");
          return;
        }

        useAppStore.setState(patch);

        setStatus(`恢复成功！已恢复 ${restored.length} 项：${restored.join("、")}`);
        setError("");
      } catch (err) {
        setError(`恢复失败：${err instanceof Error ? err.message : String(err)}`);
        setStatus("");
      }
    };
    reader.onerror = () => {
      setError("读取文件失败");
      setStatus("");
    };
    reader.readAsText(file);
    e.target.value = "";
  };

  return (
    <div className="flex flex-col gap-3">
      <div
        className="rounded-xl p-4"
        style={{ background: "var(--card)", border: "1px solid var(--card-border)" }}
      >
        <div className="mb-2 flex items-center gap-2">
          <Database className="h-5 w-5" style={{ color: "var(--accent)" }} />
          <span className="font-serif text-sm font-bold" style={{ color: "var(--text)" }}>
            选择性备份
          </span>
        </div>
        <p className="text-[11px] leading-relaxed" style={{ color: "var(--text-soft)" }}>
          自由勾选需要备份的内容，仅导出你选择的部分。恢复时也只覆盖备份文件中包含的项目。
        </p>
      </div>

      {/* 分类选择 */}
      <div
        className="rounded-xl p-3"
        style={{ background: "var(--card)", border: "1px solid var(--card-border)" }}
      >
        <div className="mb-2 flex items-center justify-between">
          <span className="text-[12px] font-medium" style={{ color: "var(--text)" }}>
            选择备份内容
          </span>
          <div className="flex items-center gap-2 text-[10px]">
            <button
              onClick={selectAll}
              className="rounded-full px-2 py-0.5 transition hover:opacity-80"
              style={{ background: "color-mix(in srgb, var(--accent) 12%, transparent)", color: "var(--accent)" }}
            >
              全选
            </button>
            <button
              onClick={selectNone}
              className="rounded-full px-2 py-0.5 transition hover:opacity-80"
              style={{ background: "color-mix(in srgb, var(--text) 8%, transparent)", color: "var(--text-soft)" }}
            >
              全不选
            </button>
          </div>
        </div>

        <div className="flex flex-col gap-1.5">
          {CATEGORIES.map((c) => {
            const isOn = !!selected[c.key];
            const sizeKB = ((sizeInfo[c.key] || 0) / 1024).toFixed(1);
            return (
              <button
                key={c.key}
                onClick={() => toggle(c.key)}
                className="flex items-center gap-2.5 rounded-lg px-2.5 py-2 text-left transition hover:bg-black/[0.03]"
                style={{
                  background: isOn ? "color-mix(in srgb, var(--accent) 6%, transparent)" : "transparent",
                }}
              >
                <span
                  className="flex h-4 w-4 shrink-0 items-center justify-center rounded border transition"
                  style={{
                    borderColor: isOn ? "var(--accent)" : "color-mix(in srgb, var(--text) 30%, transparent)",
                    background: isOn ? "var(--accent)" : "transparent",
                  }}
                >
                  {isOn && <Check className="h-3 w-3" style={{ color: "var(--card)" }} />}
                </span>
                <span className="text-[14px] leading-none">{c.emoji}</span>
                <div className="flex-1 min-w-0">
                  <div className="text-[12px] font-medium" style={{ color: "var(--text)" }}>
                    {c.label}
                  </div>
                  <div className="text-[10px] truncate" style={{ color: "var(--text-soft)" }}>
                    {c.desc}
                  </div>
                </div>
                <span className="text-[10px] shrink-0" style={{ color: "var(--text-soft)" }}>
                  {sizeKB} KB
                </span>
              </button>
            );
          })}
        </div>

        <div className="mt-2.5 flex items-center justify-between border-t pt-2 text-[11px]" style={{ borderColor: "var(--card-border)" }}>
          <span style={{ color: "var(--text-soft)" }}>
            已选 <span style={{ color: "var(--accent)", fontWeight: 600 }}>{selectedCount}</span> / {CATEGORIES.length} 项
          </span>
          <span style={{ color: "var(--text-soft)" }}>
            预估 <span style={{ color: "var(--accent)", fontWeight: 600 }}>{selectedSizeKB} KB</span> / 共 {totalSizeKB} KB
          </span>
        </div>
      </div>

      <div
        className="rounded-xl p-4"
        style={{ background: "var(--card)", border: "1px solid var(--card-border)" }}
      >
        <div className="flex flex-col gap-2">
          <button
            onClick={handleBackup}
            disabled={selectedCount === 0}
            className="flex items-center justify-center gap-2 rounded-xl py-3 text-sm font-medium transition hover:opacity-90 disabled:opacity-40 disabled:cursor-not-allowed"
            style={{
              background: "var(--accent)",
              color: "var(--card)",
            }}
          >
            <Download className="h-4 w-4" />
            下载备份文件
          </button>

          <button
            onClick={() => fileRef.current?.click()}
            className="flex items-center justify-center gap-2 rounded-xl border py-3 text-sm font-medium transition hover:bg-black/5"
            style={{
              borderColor: "var(--card-border)",
              color: "var(--text)",
            }}
          >
            <Upload className="h-4 w-4" />
            从文件恢复
          </button>
          <input
            ref={fileRef}
            type="file"
            accept="application/json,.json"
            onChange={handleRestore}
            className="hidden"
          />
        </div>
      </div>

      {status && (
        <div
          className="flex items-start gap-2 rounded-xl p-3 text-[12px]"
          style={{
            background: "color-mix(in srgb, #22c55e 15%, transparent)",
            border: "1px solid color-mix(in srgb, #22c55e 40%, transparent)",
            color: "#16a34a",
          }}
        >
          <Check className="mt-0.5 h-4 w-4 shrink-0" />
          <span>{status}</span>
        </div>
      )}

      {error && (
        <div
          className="flex items-start gap-2 rounded-xl p-3 text-[12px]"
          style={{
            background: "color-mix(in srgb, #ef4444 15%, transparent)",
            border: "1px solid color-mix(in srgb, #ef4444 40%, transparent)",
            color: "#dc2626",
          }}
        >
          <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      <div
        className="rounded-xl p-3 text-[10px] leading-relaxed"
        style={{
          background: "var(--card)",
          border: "1px solid var(--card-border)",
          color: "var(--text-soft)",
        }}
      >
        <p className="mb-1 font-medium">⚠️ 注意事项：</p>
        <ul className="list-disc space-y-0.5 pl-4">
          <li>恢复时只覆盖备份文件中包含的项目，未选中的内容保持不变</li>
          <li>兼容旧版全量备份文件（自动恢复全部字段）</li>
          <li>建议定期下载备份文件并妥善保存</li>
          <li>恢复后需要刷新页面才能完全生效</li>
        </ul>
      </div>
    </div>
  );
}
